function protocolFields(id,mode,index){if(index<0)return '';let rows=[];if(id==='arp')rows=[['EtherType','0x0806'],['Hardware / protocol','Ethernet / IPv4'],['Operation',index<2?'1 — request':'2 — reply'],['Sender IP','192.168.10.10'],['Target IP','192.168.10.20'],['Destination MAC',index<2?'ff:ff:ff:ff:ff:ff':'02:00:00:00:00:10']];else if(id==='icmp')rows=[['IP protocol','1'],['Type',mode==='PMTUD'?'3 (unreachable)':mode==='Traceroute'?'11 at an intermediate hop / destination response at final hop':index===0?'8 (echo request)':'0 (echo reply)'],['Code',mode==='PMTUD'?'4 (fragmentation needed)':'0 in the echo / time exceeded examples'],['Echo identifier','0x1234'],['Sequence',index+1]];else if(id==='dhcp'||id==='relay'){const stages=id==='relay'?['DISCOVER','DISCOVER relay','OFFER','OFFER relay','REQUEST / ACK']:['DISCOVER','OFFER','REQUEST','ACK'];rows=[['Transport','UDP'],['Client port','68'],['Server port','67'],['Message',stages[Math.min(index,stages.length-1)]],['Offered address','192.168.10.100'],['Lease example','3600 seconds'],['giaddr',id==='relay'?'192.168.10.1':'0.0.0.0'],['Option 82',mode==='Option 82'?'Circuit ID: VLAN10 / port1':'Not inserted in this scenario']];}else if(id==='nat')rows=[['Inside local','10.0.0.10'+(mode==='PAT overload'?':49152':'')],['Inside global',mode==='PAT overload'?'198.51.100.1:30001':'198.51.100.10'],['Outside global','203.0.113.80:443'],['Outside local','203.0.113.80:443'],['Mapping',mode]];else if(id==='tcp'||id==='tcp-state')rows=[['Source / destination','Example client ephemeral port / server 443'],['SYN initial sequences','Client 1000 / server 7000'],['Flags',mode==='Three-way handshake'?['SYN','SYN,ACK','ACK'][Math.min(index,2)]:mode==='Teardown'?['FIN,ACK','ACK','FIN,ACK','ACK'][Math.min(index,3)]:mode==='RST'?'RST':mode==='Data transfer'?'PSH,ACK / ACK':'See event'],['Window example','64240 bytes'],['Header without options','20 bytes']];else if(id==='dns')rows=[['Query name','lab.example'],['Record type','A'],['Transport','UDP/TCP port 53'],['RD flag','1 for a recursive client request'],['Response code',mode==='NXDOMAIN'?'3 — NXDOMAIN':'0 — NoError'],['TTL example','300 seconds']];else if(id==='tls')rows=[['Handshake version',mode==='TLS 1.2'?'TLS 1.2':'TLS 1.3'],['Cipher example','TLS_AES_128_GCM_SHA256 (TLS 1.3)'],['Key-share example','X25519'],['Authenticated name','lab.example'],['Certificate validation','Hostname, validity, chain and trust anchor']];else if(id==='ospf-neighbor'||id==='lsa-flood'||id==='virtual'||id==='protocol')rows=[['OSPF transport','IP protocol 89'],['Area','0 in the point-to-point example'],['Router IDs','1.1.1.1 / 2.2.2.2'],['Hello / dead example','10 / 40 seconds'],['Hello destination','224.0.0.5'],['Link MTU example',mode==='MTU mismatch'?'1500 / 1400':'1500 / 1500']];else if(['bgp-animation','bgp-hub'].includes(id))rows=[['Transport','TCP port 179'],['Local / remote AS','65001 / 65002'],['Message',index===0?'TCP connection':index===1?'OPEN':index===2?'KEEPALIVE':'UPDATE'],['Hold-time example','90 seconds'],['Router IDs','192.0.2.1 / 192.0.2.2']];else if(id==='mpls')rows=[['Label operation',index===0?'PUSH':index===1?'SWAP':index===2?'POP':'IP / service lookup'],['Top label',index===0?'100':index===1?'200':'Removed'],['Service label',mode==='L3VPN stack'?'24000':'None'],['Label shim length','4 bytes per label']];else if(['hijack','security'].includes(id))rows=[['Legitimate prefix','203.0.113.0/24'],['Unauthorized prefix',mode==='More-specific'?'203.0.113.0/25':'203.0.113.0/24'],['Origin result',mode==='RPKI validation'?'Invalid for unauthorized origin':'Requires validation and policy'],['Forwarding principle','Longest matching prefix']];if(!rows.length)return '';return '<h3>Illustrative packet / control fields</h3>'+table(['Field','Value'],rows);}
function tcpStateLab(){let state='CLOSED',server='LISTEN',seq=1000,ack=7000,rows=[],pending=false;$('surface').innerHTML=card('Connection parameters',`<div class="fields">${input('tcp-isn','Client initial sequence',1000,'number','min="0" max="4294967295"')}${input('tcp-sisn','Server initial sequence',7000,'number','min="0" max="4294967295"')}${input('tcp-bytes','Payload bytes',500,'number','min="1" max="65535"')}</div><div class="actions">${btn('tcp-start','Start handshake',true)}${btn('tcp-data','Send data')}${btn('tcp-loss','Lose next segment')}${btn('tcp-fin','Graceful close')}${btn('tcp-rst','Send RST')}${btn('tcp-reset','Reset')}</div>${out()}`);const wrap=n=>n%2**32;const draw=()=>{$('output').innerHTML=`<div class="topology"><div class="node ${state==='ESTABLISHED'?'selected':''}">Client<small>${state}</small></div><span class="wire"></span><div class="node ${server==='ESTABLISHED'?'selected':''}">Server<small>${server}</small></div></div>`+stats([['Client next sequence',seq],['Server next sequence',ack]])+table(['From','To','Flags','Sequence','Acknowledgment','Payload'],rows)+hint('This model uses a simple single-direction data stream with immediate ACKs. Sequence arithmetic wraps at 2^32; it does not model congestion windows or real timers.');$('tcp-start').disabled=state!=='CLOSED';['tcp-data','tcp-loss','tcp-fin'].forEach(id=>$(id).disabled=state!=='ESTABLISHED');$('tcp-rst').disabled=state==='CLOSED';};action('tcp-start',()=>{seq=Number($('tcp-isn').value);ack=Number($('tcp-sisn').value);if(![seq,ack].every(x=>Number.isInteger(x)&&x>=0&&x<2**32))throw Error('Initial sequences must be 0–4294967295.');rows.push(['Client','Server','SYN',seq,0,0]);seq=wrap(seq+1);rows.push(['Server','Client','SYN,ACK',ack,seq,0]);ack=wrap(ack+1);rows.push(['Client','Server','ACK',seq,ack,0]);state=server='ESTABLISHED';draw();});action('tcp-data',()=>{const bytes=Number($('tcp-bytes').value);if(!Number.isInteger(bytes)||bytes<1||bytes>65535)throw Error('Payload must be 1–65535 bytes.');rows.push(['Client','Server',pending?'PSH,ACK (lost)':'PSH,ACK',seq,ack,bytes]);if(pending){rows.push(['Client','Server','PSH,ACK (retransmitted)',seq,ack,bytes]);pending=false;}seq=wrap(seq+bytes);rows.push(['Server','Client','ACK',ack,seq,0]);draw();});action('tcp-loss',()=>{pending=true;toast('The next data segment will be lost, then retransmitted.');});action('tcp-fin',()=>{rows.push(['Client','Server','FIN,ACK',seq,ack,0]);seq=wrap(seq+1);rows.push(['Server','Client','ACK',ack,seq,0]);rows.push(['Server','Client','FIN,ACK',ack,seq,0]);ack=wrap(ack+1);rows.push(['Client','Server','ACK',seq,ack,0]);state='TIME-WAIT';server='CLOSED';draw();});action('tcp-rst',()=>{rows.push(['Client','Server','RST',seq,ack,0]);state=server='CLOSED';draw();});action('tcp-reset',()=>{rows=[];state='CLOSED';server='LISTEN';pending=false;draw();});draw();}
function packetTraceLab(){$('surface').innerHTML=card('Packet and routes',`<div class="fields">${input('trace-src','Source IP','192.168.10.33')}${input('trace-dst','Destination IP','203.0.113.10')}${input('trace-source-net','Source subnet','192.168.10.0/24')}${input('trace-gateway','Gateway','192.168.10.1')}</div>`+area('trace-routes','Gateway route table (CIDR via next-hop)','203.0.113.0/24 via 192.0.2.2\n0.0.0.0/0 via 192.0.2.254')+`<div class="fields">${input('trace-ttl','Initial TTL',64,'number','min="1" max="255"')}<label><input id="trace-return" type="checkbox" checked> Return route exists at destination</label></div>${btn('trace-run','Trace forwarding',true)}${out()}`);action('trace-run',()=>{const src=Net.ip($('trace-src').value),dst=Net.ip($('trace-dst').value),base=Net.subnet($('trace-source-net').value),gw=Net.ip($('trace-gateway').value),ttl=Number($('trace-ttl').value);if(src<base.start||src>base.end||gw<base.start||gw>base.end)throw Error('Source and gateway must be inside the source subnet.');if(base.p<31&&(src===base.start||src===base.end||gw===base.start||gw===base.end))throw Error('Source and gateway must be usable host addresses.');if(!Number.isInteger(ttl)||ttl<1||ttl>255)throw Error('TTL must be 1–255.');const local=dst>=base.start&&dst<=base.end;let rows=[['Host route decision',local?'Local subnet':'Use gateway '+Net.str(gw)],['ARP resolution',local?'Resolve destination MAC':'Resolve gateway MAC']];let result;if(local){rows.push(['Layer 2 delivery','Switch forwards inside the VLAN']);result='Direct local-link delivery';}else if(ttl<=1){rows.push(['Gateway TTL','TTL expires; ICMP Time Exceeded may be returned']);result='TTL expired';}else{const routes=$('trace-routes').value.split('\n').filter(x=>x.trim()).map(line=>{const [cidr,next]=line.split(/\s+via\s+/);const b=Net.subnet(cidr.trim());if(!next)throw Error('Each route needs CIDR via next-hop.');Net.ip(next.trim());return{b,next:next.trim()};}).filter(r=>dst>=r.b.start&&dst<=r.b.end).sort((a,b)=>b.b.p-a.b.p);if(!routes.length){rows.push(['Gateway lookup','No matching route']);result='Unreachable';}else{rows.push(['Longest-prefix match',routes[0].b.cidr],['Next-hop forwarding',routes[0].next],['New TTL',ttl-1],['Remote path','Forwarding beyond this gateway depends on downstream route tables'],['Return path',$('trace-return').checked?'Assumed reachable':'Missing in this scenario']);result=$('trace-return').checked?'First-hop forwarding succeeds; return path assumed':'One-way path: return routing missing';}}$('output').innerHTML=stats([['Result',result,'full']])+table(['Step','Decision'],rows)+hint('This packet walk validates local delivery or one gateway lookup. It does not claim end-to-end reachability without modeling downstream routers.');});$('trace-run').click();}
